  wire ext_tx, ext_bootloader_ready, ext_wave, ext_wave1, ext_wave2;
  wire [7:0] core_bootloader_data;
  wire core_bootloader_ready, core_bootloader_write, core_clk,
       core_rst, core_tx, core_wave, core_wave1, core_wave2;
  pc3d01 \gen_bl_data_pads[0].pad_bl_data (.PAD
       (ext_bootloader_data[0]), .CIN (core_bootloader_data[0]));
  pc3d01 \gen_bl_data_pads[1].pad_bl_data (.PAD
       (ext_bootloader_data[1]), .CIN (core_bootloader_data[1]));
  pc3d01 \gen_bl_data_pads[2].pad_bl_data (.PAD
       (ext_bootloader_data[2]), .CIN (core_bootloader_data[2]));
