  pc3d01 \gen_bl_data_pads[6].pad_bl_data (.PAD
       (ext_bootloader_data[6]), .CIN (core_bootloader_data[6]));
  pc3d01 \gen_bl_data_pads[7].pad_bl_data (.PAD
       (ext_bootloader_data[7]), .CIN (core_bootloader_data[7]));
  pt3t03u pad_bl_ready(.PAD (ext_bootloader_ready), .I
       (core_bootloader_ready), .OEN (1'b0));
  pc3d01 pad_bl_write(.PAD (ext_bootloader_write), .CIN
       (core_bootloader_write));
  pc3d01 pad_clk(.PAD (ext_clk), .CIN (core_clk));
  pc3d01 pad_rst(.PAD (ext_rst), .CIN (core_rst));
